import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ProductionFixDemo {

    private static final Logger log = Logger.getLogger(ProductionFixDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Dry-run-first bulk update guardrail at " + BANK_NAME);

        List<Account> accounts = new ArrayList<>();
        accounts.add(new Account("SAV2001", "SAVINGS", false));
        accounts.add(new Account("CUR3001", "CURRENT", false));
        accounts.add(new Account("SAV2002", "SAVINGS", false));

        BulkUpdater updater = new BulkUpdater(accounts);

        // The original dangerous filter: matches ALL accounts (too broad).
        Predicate<Account> tooBroad = a -> true;
        log.warning("Dry run with the ORIGINAL (buggy) filter — matches everything:");
        int wouldChange = updater.dryRun(tooBroad);
        log.warning(() -> "Dry run shows " + wouldChange
                + " accounts would change. That is too many — filter is wrong. NOT applying.");

        // The corrected filter: only SAVINGS accounts should get the flag.
        Predicate<Account> correct = a -> "SAVINGS".equals(a.getType());
        log.info("Dry run with the CORRECTED filter — savings only:");
        int wouldChangeCorrect = updater.dryRun(correct);
        log.info(() -> "Dry run shows " + wouldChangeCorrect + " accounts would change. Looks right.");

        // Apply only after a reviewer confirms.
        boolean confirmed = true;
        int changed = updater.apply(correct, true, confirmed);
        log.info(() -> "Applied safely: " + changed + " savings accounts updated.");
    }
}

