class Account {
    private final String accountId;
    private final String type;
    private boolean interestFlag;

    Account(String accountId, String type, boolean interestFlag) {
        this.accountId = accountId;
        this.type = type;
        this.interestFlag = interestFlag;
    }

    String getAccountId() { return accountId; }
    String getType() { return type; }
    boolean isInterestFlag() { return interestFlag; }
    void setInterestFlag(boolean interestFlag) { this.interestFlag = interestFlag; }
}

// ─── Would be in ops/BulkUpdater.java in a real project ───
class BulkUpdater {
    private static final Logger log = Logger.getLogger(BulkUpdater.class.getName());
    private final List<Account> accounts;

    BulkUpdater(List<Account> accounts) {
        this.accounts = accounts;
    }

    // Dry run: report impact, change nothing.
    int dryRun(Predicate<Account> filter) {
        int count = 0;
        for (Account a : accounts) {
            if (filter.test(a)) {
                count++;
                log.fine(() -> "WOULD set interestFlag=true for " + a.getAccountId());
            }
        }
        return count;
    }

    // Apply: change data, but only with dry-run done and explicit confirmation.
    int apply(Predicate<Account> filter, boolean dryRunCompleted, boolean confirmed) {
        if (!dryRunCompleted || !confirmed) {
            log.severe("Refusing to apply: dry run and confirmation are required.");
            return 0;
        }
        int count = 0;
        for (Account a : accounts) {
            if (filter.test(a)) {
                a.setInterestFlag(true);
                count++;
                log.info(() -> "Set interestFlag=true for " + a.getAccountId());
            }
        }
        return count;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
